        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 365 days);

        address sender = address(0xABCD);
        vm.deal(sender, amount);
        vm.prank(sender);
        c.Put{value: amount}(unlockTime);

        // Acc is a public mapping, so the getter returns (uint256 unlockTime, uint256 balance)
        (, uint256 recordedBalance) = c.Acc(sender);
        // The invariant: recorded balance must be at least the amount sent in this Put call
        assertTrue(recordedBalance >= amount);
    }
}

