pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // Keep the amount in an admissible range: positive and not exceeding the actor's balance.
        // Use a generous upper bound to allow the fuzzer to explore the space.
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint128).max);

        address actor = address(0x1234);
        vm.deal(actor, amount);

        uint256 balanceBefore = address(c).balance;
        (bool rv1, bytes memory ret1) = address(c).staticcall(abi.encodeWithSignature("Acc(address)", actor));
        require(rv1, "staticcall failed");
        uint256 accBefore = abi.decode(ret1, (uint256, uint256));
        uint256 senderBalBefore = accBefore;

        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", unlockTime));
        require(ok, "Put call failed");

        uint256 balanceAfter = address(c).balance;
        (bool rv2, bytes memory ret2) = address(c).staticcall(abi.encodeWithSignature("Acc(address)", actor));
        require(rv2, "staticcall failed");
        uint256 accAfter = abi.decode(ret2, (uint256, uint256));
        uint256 senderBalAfter = accAfter;

        uint256 deltaBalance = balanceAfter - balanceBefore;
        uint256 deltaAcc = senderBalAfter - senderBalBefore;
        assertTrue(deltaBalance == deltaAcc + amount);
    }
}

