pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint256 collectAmt, uint256 balanceBefore, uint256 warpAfter) public {
        // Restrict to reasonable domain; avoid overflow in Collect collectAmt <= balance after Put
        vm.assume(balanceBefore < type(uint128).max);
        vm.assume(collectAmt > 0);
        vm.assume(collectAmt <= c.MinSum()); // Collect requires >= MinSum

        // Warp to a known future time so block.timestamp is not trivially 0/1
        uint256 startTime = 1000;
        vm.warp(startTime);

        address user = address(0x100);
        vm.deal(user, balanceBefore);
        vm.prank(user);
        c.Put{value: balanceBefore}(unlockTime);

        uint256 recordedUnlock = c.Acc(user).unlockTime;
        uint256 putTimestamp = startTime; // vm.warp set this

        // Warp forward; must exceed recorded unlock time for Collect to succeed
        vm.warp(warpAfter);

        // Collect attempt
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmt));

        // General rule: if unlockTime < block.timestamp of Put call, then in the reference,
        // recordedUnlock will be >= block.timestamp of Put call, so a later collect after warp
        // may succeed only when warpAfter > recordedUnlock. Actually, the property we assert:
        // The unlockTime stored is always >= the Put's block.timestamp.
        // The bug allows it to be strictly less, leading to a different Collect success.
        // So we assert: recordedUnlock >= putTimestamp.
        // But the bug can set a past unlockTime, making recordedUnlock < putTimestamp.
        assertTrue(recordedUnlock >= putTimestamp);
    }
}

