pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint128 collectAmount) public {
        // Bound collectAmount to a safe range (non-zero, <= type(uint128).max)
        vm.assume(collectAmount > 0);

        address user = address(0x1000);
        uint256 depositAmount = uint256(collectAmount) + 1 ether; // ensure balance >= MinSum
        vm.deal(user, depositAmount);

        // Record block.timestamp before Put
        uint256 putTimestamp = block.timestamp;

        // Advance time into the future so unlockTime can be set ahead
        uint256 futureTimestamp = block.timestamp + 1000;
        vm.warp(futureTimestamp);

        vm.startPrank(user);
        c.Put{value: depositAmount}(unlockTime);
        vm.stopPrank();

        // Now move time to max(putTimestamp + 1, unlockTime) and attempt Collect
        uint256 targetTime = putTimestamp + 1;
        if (unlockTime > targetTime) {
            targetTime = unlockTime;
        }
        if (targetTime > block.timestamp) {
            vm.warp(targetTime);
        }

        vm.startPrank(user);
        bool ok = true;
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }
        vm.stopPrank();

        // Assertion: if block.timestamp > putTimestamp (which is always true now),
        // then the Collect attempt must succeed ONLY if unlockTime was set >= putTimestamp+1
        // (i.e., the reference enforces unlockTime >= futureTimestamp which is > putTimestamp,
        // so it will fail when unlockTime < futureTimestamp, while the bug allows it to succeed).
        // We assert that success implies unlockTime >= putTimestamp + 1.
        // More precisely: Collect success → unlockTime was set to a value >= block.timestamp of Put.
        // Since we warped to exactly putTimestamp + 1 (if unlockTime <= putTimestamp) or unlockTime,
        // success means either unlockTime was >= futureTimestamp (reference) or any value (bug).
        // To capture the difference: for unlockTime < futureTimestamp, reference fails, bug succeeds.
        // So rule: if unlockTime < futureTimestamp (the block.timestamp at Put), Collect must fail.
        // We add a condition: if unlockTime < futureTimestamp, assertFalse(ok).
        // But the property must hold for all inputs; we invert: assertTrue((unlockTime >= futureTimestamp) || !ok).

        assertTrue((unlockTime >= futureTimestamp) || !ok);
    }
}

