    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, uint256 unlockTime) public {
        // Bound deposit to reasonable range to set up state
        depositAmt = bound(depositAmt, 1 ether, 1000 ether);
        // UnlockTime must be in the past after warp for Collect to succeed
        unlockTime = bound(unlockTime, 1, block.timestamp + 365 days);
        // Collect amount must be positive and <= deposited
