        vm.warp(unlockTime + 1);

        // Collect attempt
        vm.prank(user);
        try c.Collect(collectAmt) {} catch {}

        // After Collect (whether it executed or not), check invariant:
        // If balance was >= MinSum and the Collect succeeded, the resulting balance must still be >= MinSum.
        // This holds in reference because acc.balance >= MinSum is a prerequisite; bug omits it.
        uint256 balAfter = c.Acc(user);
        uint256 min = c.MinSum();
        if (balAfter < min) {
            // In reference, this can only happen if the collect did NOT execute (balance was below min).
            // In bug, it can happen after a successful collect that reduced balance below min.
            // We assert that either balance was already < min before collect (impossible due to deposit >= 1 ether)
            // or collect did not execute (balance unchanged). But since we control deposit >= 1 ether,
            // balance starts >= min. So the invariant is: balAfter >= min.
            // However, the reference may still fail if collectAmt > balAfter? No, collectAmt <= depositAmt = balAfter.
            // So reference: balAfter >= min always. Bug: balAfter can be < min.
            assertTrue(false);
        } else {
            assertTrue(true);
        }
    }
}

